import requests

def test_post_api_auth_verify_otp_with_invalid_or_expired_code():
    base_url = "http://localhost:8000"
    url = f"{base_url}/api/auth/verify-otp"
    headers = {
        "Authorization": "Bearer eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    }
    # Use an invalid/expired OTP code as payload with correct field name
    payload = {
        "email": "testsprite.driver+invalidotp@example.com",
        "otp": "000000"
    }
    try:
        response = requests.post(url, json=payload, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"
    # Accept 400, 401 or 410 for verification failure
    assert response.status_code in (400, 401, 410), f"Unexpected status code: {response.status_code} with body: {response.text}"

test_post_api_auth_verify_otp_with_invalid_or_expired_code()
